//! The Material colour palette, from upstream `material/colors.dart`.
//!
//! Two thousand lines of constants upstream, and the same constants here --
//! generated by parsing that file rather than typed out, because a palette
//! transcribed by hand is a palette with one wrong digit in it somewhere.
//!
//! A [`MaterialColor`] is a swatch: a primary colour and the ten shades
//! around it, keyed by weight. Upstream it is a `ColorSwatch<int>`, and it
//! *is* a `Color` as well -- `Colors.red` can be used where a colour is
//! wanted and means `Colors.red[500]`. There is no inheritance here, so a
//! swatch has [`MaterialColor::color`] and the shade accessors, and the
//! call site says which it wants.
//!
//! # Recorded divergences
//!
//! * Upstream's swatches are `ColorSwatch<int>` and indexable with `[]`.
//!   Here [`MaterialColor::shade`] takes the weight and answers an option,
//!   which is the same lookup with the missing case in the type.
//! * `Colors.primaries` and `Colors.accents` are the two lists upstream
//!   keeps for demos that walk the palette; they are here as
//!   [`Colors::PRIMARIES`] and [`Colors::ACCENTS`].

use crate::engine::Color;

/// Upstream `MaterialColor`: a primary colour and the shades around it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct MaterialColor {
    /// The swatch's own colour -- upstream's `Color` half, which is the 500
    /// shade for a primary swatch and 200 for an accent one.
    pub color: Color,
    shades: [(u32, Color); MaterialColor::WIDEST],
    /// How many of `shades` are real; an accent swatch has four.
    count: usize,
}

impl MaterialColor {
    /// How many shades the widest swatch has -- upstream's `grey`, which
    /// carries a 350 and an 850 the others do not.
    pub const WIDEST: usize = 12;

    const fn new(
        color: Color,
        shades: [(u32, Color); MaterialColor::WIDEST],
        count: usize,
    ) -> MaterialColor {
        MaterialColor {
            color,
            shades,
            count,
        }
    }

    /// The shade at that weight, or `None` if the swatch has no such shade --
    /// upstream's `operator []`, which answers null the same way.
    pub fn shade(&self, weight: u32) -> Option<Color> {
        self.shades[..self.count]
            .iter()
            .find(|(at, _)| *at == weight)
            .map(|(_, colour)| *colour)
    }

    /// Every weight this swatch has, lightest first.
    pub fn weights(&self) -> impl Iterator<Item = u32> + '_ {
        self.shades[..self.count].iter().map(|(at, _)| *at)
    }
}

/// Upstream `MaterialAccentColor`: the four-shade accent swatch. The same
/// type here, since the only difference is which weights it has.
pub type MaterialAccentColor = MaterialColor;

