#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_swatch_is_its_own_five_hundred() {
        // Upstream's `MaterialColor(_redPrimaryValue, ...)` and its 500 entry
        // are the same constant, which is what makes `Colors.red` usable
        // where a colour is wanted.
        assert_eq!(Colors::RED.color, Color(0xfff44336));
        assert_eq!(Colors::RED.shade(500), Some(Colors::RED.color));
        assert_eq!(Colors::RED.shade(50), Some(Color(0xffffebee)));
        assert_eq!(Colors::RED.shade(900), Some(Color(0xffb71c1c)));
        assert_eq!(Colors::RED.shade(250), None, "no such weight");
    }

    #[test]
    fn an_accent_swatch_has_four_shades_and_is_its_own_two_hundred() {
        assert_eq!(
            Colors::RED_ACCENT.weights().collect::<Vec<_>>(),
            vec![100, 200, 400, 700]
        );
        assert_eq!(
            Colors::RED_ACCENT.shade(200),
            Some(Colors::RED_ACCENT.color)
        );
        assert_eq!(Colors::RED_ACCENT.shade(500), None);
    }

    #[test]
    fn the_greys_and_the_transparencies_are_upstreams() {
        assert_eq!(Colors::TRANSPARENT, Color(0x00000000));
        assert_eq!(Colors::BLACK, Color(0xff000000));
        assert_eq!(Colors::BLACK54, Color(0x8a000000));
        assert_eq!(Colors::WHITE, Color(0xffffffff));
        assert_eq!(Colors::WHITE70, Color(0xb3ffffff));
        // Grey is a primary swatch, and its 500 is the one everything else
        // is measured against.
        assert_eq!(Colors::GREY.shade(500), Some(Colors::GREY.color));
    }

    #[test]
    fn every_primary_swatch_is_its_own_five_hundred_and_every_accent_its_two() {
        for swatch in Colors::PRIMARIES {
            // Ten weights, except grey, which carries a 350 and an 850 for
            // the raised button's pressed fill.
            assert!(matches!(swatch.weights().count(), 10 | 12));
            assert_eq!(swatch.shade(500), Some(swatch.color));
        }
        for swatch in Colors::ACCENTS {
            assert_eq!(swatch.weights().count(), 4);
            assert_eq!(swatch.shade(200), Some(swatch.color));
        }
        assert_eq!(Colors::GREY.weights().count(), 12);
        assert_eq!(Colors::GREY.shade(350), Some(Color(0xffd6d6d6)));
    }
}
